export const alive=b=>b.units.filter(u=>u.hp>0&&!u.dead);
export const actor=b=>b.units.find(u=>u.id===b.active);
export function log(b,text,detail=null){if(b.telemetry&&detail){const t=b.telemetry,a=b.units.find(u=>u.id===detail.actor),z=b.units.find(u=>u.id===detail.target);if(detail.timeline&&detail.key)t.actions[detail.key]=(t.actions[detail.key]||0)+1;if(Number.isFinite(detail.damage)){const lost=detail.healthLost??detail.damage;if(a&&a!==z)t.damage[a.team]+=lost;if(z)t.received[z.team]+=lost;}if(a&&detail.outcome){if(['success','criticalSuccess'].includes(detail.outcome))t.hits[a.team]++;else t.misses[a.team]++;if(detail.outcome==='criticalSuccess')t.critical[a.team]++;}if(detail.condition&&detail.severity)t.conditions[detail.condition]=(t.conditions[detail.condition]||0)+1;if(detail.interrupted)t.interruptions++;}if(b.experiment&&!b.keepLog)return;b.log.push({t:b.time,text,visible:!b.map.fog||b.units.some(u=>(u.id===detail?.actor||u.id===detail?.target||(!detail?.actor&&!detail?.target&&text.includes(u.name)))&&visibleTo(b,0,u))||/^(Battle|Team [12] wins)/.test(text),...(detail?{detail}:{})});if(b.log.length>(b.experiment&&b.keepLog?50000:1000))b.log.shift();}
export function breakGrapple(b,u){for(const id of [u.grappledBy,u.grappling]){const other=b.units.find(v=>v.id===id);if(other){if(other.grappledBy===u.id)other.grappledBy=null;if(other.grappling===u.id)other.grappling=null;}}u.grappledBy=null;u.grappling=null;}
