 // Use the slowest adequate movement, favoring careful footwork when sufficient.
 for(const k of modes){const maxSpeed=Math.max(.05,c.max.move*movementMode(k).budget/(2.4*.55*movementMode(k).delay)*channel(c,'movement')*channel(c,'control'));if(maxSpeed*dt>=distanceNeeded-1e-7){kind=k;break;}}
