function finish(b){cleanRelations(b);for(const u of b.units)if(u.job?.key==='move'&&u.job.phase!=='recovery'&&(stunned(u)||immobilized(u)||u.grappledBy||u.grappling))endMovement(b,u,u.job,'movement impaired');for(const u of b.units)if(incapacitated(u)){if(u.job){if(u.job.key==='move'&&u.job.phase!=='recovery')endMovement(b,u,u.job,'incapacitated');u.next=Math.max(b.time,u.next);u.job=null;}if(u.grappling||u.grappledBy)breakGrapple(b,u);}const sides=new Set(alive(b).map(u=>u.team));let result=null;const o=b.objective;if(o&&o.kind!=='elimination'){const ally=alive(b).filter(u=>u.team===0);if(['protect','escape'].includes(o.kind)&&!ally.some(u=>u.id==='A1'))result=1;else if(o.kind==='escape'&&ally.some(u=>u.id==='A1'&&inside(u,b.map.zones[1])))result=0;else if(b.time>=o.seconds-1e-8){if(o.kind==='survive'||o.kind==='protect')result=ally.length?0:1;else if(o.kind==='escape')result=1;else if(o.kind==='control'){const count=side=>alive(b).filter(u=>u.team===side&&dist(u,{x:b.map.w/2,y:b.map.h/2})<=o.radius).length;result=count(0)===count(1)?2:count(0)>count(1)?0:1;}}}if(result===null&&o&&o.kind!=="elimination"&&sides.size){if(!sides.has(0)&&o.kind!=="control")result=1;else if(b.turns<(b.maxTurns??1500))return false;}if(result===null&&sides.size>=2&&b.turns<(b.maxTurns??1500))return false;b.winner=result??(o&&o.kind!=="elimination"?2:sides.size===1?[...sides][0]:2);b.active=null;for(const u of b.units){if(u.job?.key==='move'&&u.job.phase!=='recovery')endMovement(b,u,u.job,'battle ended');u.job=null;}log(b,b.winner===2?'Battle drawn.':`Team ${b.winner+1} wins.`);recordFrame(b,'Battle complete');return true;}
function scheduleJob(b,c,key,phases,extra={}){const start=b.time,prepEnd=start+phases.preparation,impactAt=prepEnd+phases.execution,end=impactAt+phases.recovery;c.job={key,phase:'preparation',start,prepEnd,impactAt,end,at:prepEnd,phases,...extra};c.next=end;b.active=null;b.moved=false;log(b,`${c.name} prepares ${key==='move'?'movement':ACTIONS[key].label.toLowerCase()}.`,{timeline:true,actor:c.id,key,phases,impactAt,end});recordFrame(b,`${c.name}: preparation`);}
// One event or decision at a time, with deterministic effect-before-readiness ties.
// A committed action never rolls its dice until its impact event.
